const MAX_SAFE = Number.MAX_SAFE_INTEGER;

export function rangeToRegex(min, max) {
  if (min > max) [min, max] = [max, min];
  if (!Number.isInteger(min) || !Number.isInteger(max)) {
    throw new TypeError('range bounds must be integers');
  }
  if (min < 0) throw new RangeError('range bounds must be non-negative');
  if (max > MAX_SAFE) throw new RangeError('range bounds exceed MAX_SAFE_INTEGER');

  const parts = [];
  const minLen = String(min).length;
  const maxLen = String(max).length;

  for (let len = minLen; len <= maxLen; len++) {
    const segLow = len === 1 ? 0 : 10 ** (len - 1);
    const segHigh = 10 ** len - 1;
    const lo = Math.max(min, segLow);
    const hi = Math.min(max, segHigh);
    if (lo > hi) continue;
    parts.push(fixedLength(lo, hi, len));
  }

  return parts.length === 1 ? parts[0] : `(${parts.join('|')})`;
}

function fixedLength(lo, hi, len) {
  const loStr = String(lo).padStart(len, '0');
  const hiStr = String(hi).padStart(len, '0');
  return build(loStr, hiStr);
}

function build(lo, hi) {
  const n = lo.length;
  if (lo === hi) return lo;
  if (lo === '0'.repeat(n) && hi === '9'.repeat(n)) return '[0-9]'.repeat(n);

  if (n === 1) return charClass(lo, hi);

  if (lo[0] === hi[0]) {
    return lo[0] + build(lo.slice(1), hi.slice(1));
  }

  const parts = [];
  parts.push(lo[0] + build(lo.slice(1), '9'.repeat(n - 1)));
  const midLow = Number(lo[0]) + 1;
  const midHigh = Number(hi[0]) - 1;
  if (midLow <= midHigh) {
    parts.push(digitClass(midLow, midHigh) + '[0-9]'.repeat(n - 1));
  }
  parts.push(hi[0] + build('0'.repeat(n - 1), hi.slice(1)));

  return `(${parts.join('|')})`;
}

function charClass(lo, hi) {
  return lo === hi ? lo : `[${lo}-${hi}]`;
}

function digitClass(lo, hi) {
  if (lo === hi) return String(lo);
  if (lo === 0 && hi === 9) return '[0-9]';
  return `[${lo}-${hi}]`;
}
```

