import { rangeToRegex, rangeToRegExp } from '../src/range-to-regex.js';

test('converts the canonical 1-100 example', () => {
  assert.equal(rangeToRegex(1, 100), '([1-9]|(1[0-9]|[2-8][0-9]|9[0-9])|100)');
