  for (let min = 0; min <= 60; min += 3) {
    for (let max = min; max <= 60; max += 7) {
      const regex = rangeToRegExp(min, max);
      for (let n = 0; n <= 80; n += 1) {
        assert.equal(regex.test(String(n)), n >= min && n <= max, `range ${min}-${max}, value ${n}`);
      }
    }
  }
});

